import React from 'react';
import { View, TouchableOpacity, Text, StyleSheet, Platform } from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import Feather from 'react-native-vector-icons/Feather';

export default function BottomActionBar({
  onNovoEnsaio,
  onNovoDevocional,
  onEditarDevocional,
  onPlayDevocional,
}) {
  return (
    <View style={styles.wrapper}>
      <LinearGradient
        colors={['#3a256b', '#4b1e6d', '#2d145e']}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={styles.container}
      >
        <BarButton iconName="book-open" label="+Agenda" onPress={onNovoEnsaio} />
        <BarButton iconName="plus-circle" label="+Link" onPress={onNovoDevocional} />
        {onPlayDevocional && <BarButton youtube label="Play" onPress={onPlayDevocional} />}
        <BarButton iconName="edit-3" label="Editar" onPress={onEditarDevocional} />
      </LinearGradient>
    </View>
  );
}

function BarButton({ iconName, label, onPress, youtube = false }) {
  return (
    <View style={styles.slot}>
      <TouchableOpacity style={[styles.actionBtn, styles.skeuoBtn]} onPress={onPress} activeOpacity={0.85}>
        <View style={styles.iconBox}>
          {youtube ? (
            <View style={styles.youtubeIcon}>
              <Feather name="play" size={16} color="#fff" style={styles.youtubePlay} />
            </View>
          ) : (
            <Feather name={iconName} size={28} color="#FF9A3C" style={styles.icon} />
          )}
        </View>
        <Text style={styles.label} numberOfLines={1} adjustsFontSizeToFit>
          {label}
        </Text>
      </TouchableOpacity>
    </View>
  );
}

